using System.Linq; using System.Web.Mvc; using System.Web.Security; using MyStoreCustomer.Models;
namespace MyStoreCustomer.Controllers { public class AccountController:Controller { private StoreDbContext db=new StoreDbContext(); [AllowAnonymous,HttpGet] public ActionResult Login(){return View();} [AllowAnonymous,HttpPost,ValidateAntiForgeryToken] public ActionResult Login(LoginViewModel m){var u=db.Users.FirstOrDefault(x=>x.Username==m.Username&&x.PasswordHash==m.Password);if(u==null){ModelState.AddModelError("","Tên đăng nhập hoặc mật khẩu không đúng.");return View(m);}FormsAuthentication.SetAuthCookie(u.Username,false);return RedirectToAction("MyOrder","Customer");} [AllowAnonymous,HttpGet] public ActionResult Register(){return View();} [AllowAnonymous,HttpPost,ValidateAntiForgeryToken] public ActionResult Register(RegisterViewModel m){if(db.Users.Any(x=>x.Username==m.Username)){ModelState.AddModelError("Username","Tên đăng nhập đã tồn tại.");return View(m);}db.Users.Add(new AppUser{Username=m.Username,PasswordHash=m.Password,Role="Customer"});db.Customers.Add(new Customer{Username=m.Username,CustomerName=m.CustomerName,CustomerPhone=m.CustomerPhone,CustomerEmail=m.CustomerEmail,CustomerAddress=m.CustomerAddress});db.SaveChanges();FormsAuthentication.SetAuthCookie(m.Username,false);return RedirectToAction("MyOrder","Customer");} [HttpPost,Authorize,ValidateAntiForgeryToken] public ActionResult Logout(){FormsAuthentication.SignOut();return RedirectToAction("Login");} protected override void Dispose(bool d){if(d)db.Dispose();base.Dispose(d);} } }